#Requires -Version 5.1
# VERSION 1.0.0
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$P=Join-Path $PSScriptRoot 'Invocar-ClaudeMem-Copilot.ps1';$H=Join-Path $PSScriptRoot 'Gestionar-Historial-Contextos-ClaudeMem.ps1';$R=@();$C=&$P -Consulta 'ClaudeMem memoria integracion' -Nivel 2 -MaxCaracteres 4000 -OmitirAuditoriaPrevia;$R+=[pscustomobject]@{Estado=$(if($C.resultados-gt0){'PASS'}else{'FAIL'});Prueba='Consulta'};$Lista=@(&$H -Listar -Ultimos 5);$R+=[pscustomobject]@{Estado=$(if($Lista.Count-gt0){'PASS'}else{'FAIL'});Prueba='Historial'};$R+=[pscustomobject]@{Estado=$(if(-not($C.markdown-match'(?m)^\s*\{"')){'PASS'}else{'FAIL'});Prueba='Legibilidad'};$R+=[pscustomobject]@{Estado=$(if($C.caracteresUsados-le4000){'PASS'}else{'FAIL'});Prueba='Presupuesto'};$R|Format-Table -AutoSize;$A=@($R|Where-Object{[string]$_.Estado-eq'PASS'}).Count;Write-Host "Aprobadas: $A / $($R.Count)";if($A-ne$R.Count){exit 1}
